// 16 levels in 4 worlds + a sandbox. Rows list inputs MSB-first for display only.
// On-chain tables are generated by scripts/onchain-levels.js (eval packs input k = bit k, output k = bit k).
// Worlds 2-4 can also be taped out and submitted on X Layer. `fabx` + `ref` come from FabX's public taskbank (refNand = FabX's reference gate count).
const f = (n, fn) => Array.from({length: 1 << n}, (_, i) => {
  const ins = Array.from({length: n}, (_, b) => (i >> (n - 1 - b)) & 1);
  return [ins, [].concat(fn(...ins))];
});
window.WORLDS = [
  {id: 1, name: "GATES",        sub: "Build every logic gate from NAND. Free, in your browser."},
  {id: 2, name: "LOGIC",        sub: "Decisions and voting. Your circuits are checked on X Layer."},
  {id: 3, name: "ARITHMETIC",   sub: "Teach wires to count."},
  {id: 4, name: "FABX BOUNTIES", sub: "Real FabX mining tasks. Match or beat FabX's reference design."}
];
const mk = (id, world, title, text, inputs, outputs, rows, maxGates, extra = {}) =>
  Object.assign({id, world, title, text, inputs, outputs, rows, maxGates, onchain: world > 1}, extra);
window.LEVELS = [
  mk(1, 1, "NOT", "NAND outputs 0 only when both inputs are 1. Build NOT: output the opposite of A. Hint: feed A into both inputs.", ["A"], ["Y"], f(1, a => 1 - a), 1, {fabx: "GC-001", ref: 3}),
  mk(2, 1, "AND", "Y is 1 only when A and B are both 1. Hint: NAND, then invert.", ["A", "B"], ["Y"], f(2, (a, b) => a & b), 2, {fabx: "GC-003", ref: 4}),
  mk(3, 1, "OR", "Y is 1 when A or B (or both) is 1. Hint: invert each input first.", ["A", "B"], ["Y"], f(2, (a, b) => a | b), 3, {fabx: "GC-004", ref: 5}),
  mk(4, 1, "NOR", "Y is 1 only when both A and B are 0. Hint: you already built OR.", ["A", "B"], ["Y"], f(2, (a, b) => 1 - (a | b)), 4, {fabx: "GC-005", ref: 6}),
  mk(5, 1, "XOR", "Y is 1 when A and B differ. This one is famous: four NANDs, and one feeds two others.", ["A", "B"], ["Y"], f(2, (a, b) => a ^ b), 4, {fabx: "GC-006", ref: 6}),

  mk(6, 2, "XNOR", "Y is 1 when A and B are the same. Hint: XOR, inverted.", ["A", "B"], ["Y"], f(2, (a, b) => 1 - (a ^ b)), 5, {fabx: "GC-007", ref: 7}),
  mk(7, 2, "Multiplexer", "Y = A when S is 0, B when S is 1. A switch made of logic.", ["S", "A", "B"], ["Y"], f(3, (s, a, b) => s ? b : a), 4, {fabx: "GC-009", ref: 6}),
  mk(8, 2, "Majority vote", "Y is 1 when at least two of A, B, C are 1. Hint: three pairs, ANDed, then ORed.", ["A", "B", "C"], ["Y"], f(3, (a, b, c) => (a + b + c) >= 2 ? 1 : 0), 6, {fabx: "GC-008", ref: 8}),
  mk(9, 2, "Parity", "Y is 1 when an odd number of A, B, C are 1. Hint: XOR chains.", ["A", "B", "C"], ["Y"], f(3, (a, b, c) => a ^ b ^ c), 8),

  mk(10, 3, "Comparator", "Y is 1 when A is greater than B (A=1, B=0). Three gates is possible.", ["A", "B"], ["Y"], f(2, (a, b) => a & (1 - b)), 3),
  mk(11, 3, "Half adder", "Add two bits. Outputs S (sum) and C (carry). Hint: S is XOR and C is AND, and they share a gate.", ["A", "B"], ["S", "C"], f(2, (a, b) => [a ^ b, a & b]), 5),
  mk(12, 3, "Full adder", "Add A + B + Cin. Outputs S and Cout. A classic nine-gate design exists.", ["A", "B", "Cin"], ["S", "Cout"], f(3, (a, b, c) => [a ^ b ^ c, (a & b) | (c & (a ^ b))]), 9),
  mk(13, 3, "2-bit adder", "Boss level. Add the 2-bit numbers (A1 A0) + (B1 B0). Outputs S0, S1 and carry C. Chain a half adder into a full adder.", ["A0", "A1", "B0", "B1"], ["S0", "S1", "C"],
    f(4, (a0, a1, b0, b1) => { const s = (a0 + 2 * a1) + (b0 + 2 * b1); return [s & 1, (s >> 1) & 1, (s >> 2) & 1]; }), 14),

  mk(14, 4, "Bounty GC-001 · Inverter", "FabX task GC-001: a single-bit inverter. FabX's reference uses 3 gates. Prove the design here; then build the same circuit on fabx.tech to claim the task.", ["A"], ["Y"], f(1, a => 1 - a), 1, {fabx: "GC-001", ref: 3, graduation: true}),
  mk(15, 4, "Bounty GC-003 · AND gate", "FabX task GC-003: a two-input AND. FabX's reference uses 4 gates.", ["A", "B"], ["Y"], f(2, (a, b) => a & b), 2, {fabx: "GC-003", ref: 4, graduation: true}),
  mk(16, 4, "Bounty GC-006 · XOR gate", "FabX task GC-006: a two-input XOR. FabX's reference uses 6 gates. Can you beat it?", ["A", "B"], ["Y"], f(2, (a, b) => a ^ b), 4, {fabx: "GC-006", ref: 6, graduation: true})
];
// Free build: no goal, the truth table of whatever you wire is computed live. Not part of progression.
window.SANDBOX = {id: 99, world: 0, title: "Sandbox", text: "Free build. Wire anything from A, B, C. The truth table shows what your circuit actually does.", inputs: ["A", "B", "C"], outputs: ["Y"], rows: [], maxGates: 0, onchain: false, sandbox: true};
